package cn.mop.persistence;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.Instant;
import cn.mop.domain.change.ChangeNoticeDraft;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
/** Restricted real PostgreSQL schema checks. Most rows roll back; one committed synthetic draft is retained. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresChangeNoticeSchemaIntegrationTest {
    static HikariDataSource pool;
    static final String TENANT="55000000-0000-4000-8000-000000000001";
    Connection c;String actor,asset,otherAsset,foreignAsset;
    @BeforeAll static void connect(){String url=System.getenv("SPRING_DATASOURCE_URL");assertNotNull(url);assertTrue(url.matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));var cfg=new HikariConfig();cfg.setJdbcUrl(url);cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(2);cfg.setConnectionTimeout(5000);pool=new HikariDataSource(cfg);}
    @BeforeEach void begin()throws Exception{c=pool.getConnection();c.setAutoCommit(false);actor=scalar("SELECT user_id::text FROM public.mop_membership WHERE tenant_id='"+TENANT+"' AND role_code='padmin' AND active ORDER BY user_id LIMIT 1");asset=scalar("SELECT id::text FROM public.mop_asset WHERE tenant_id='"+TENANT+"' ORDER BY id LIMIT 1");otherAsset=scalar("SELECT id::text FROM public.mop_asset WHERE tenant_id='"+TENANT+"' ORDER BY id OFFSET 1 LIMIT 1");foreignAsset=scalar("SELECT id::text FROM public.mop_asset WHERE tenant_id<>'"+TENANT+"' ORDER BY id LIMIT 1");}
    @AfterEach void rollback()throws Exception{if(c!=null){c.rollback();c.close();}}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    void sql(String value)throws SQLException{try(var s=c.createStatement()){s.execute(value);}}
    String scalar(String value)throws SQLException{try(var s=c.createStatement();var r=s.executeQuery(value)){assertTrue(r.next());return r.getString(1);}}
    @FunctionalInterface interface Action{void run()throws Exception;}
    void rejected(String state,Action action)throws Exception{var p=c.setSavepoint();var e=assertThrows(SQLException.class,action::run);assertEquals(state,e.getSQLState());c.rollback(p);c.releaseSavepoint(p);}
    void validate()throws SQLException{sql("SET CONSTRAINTS ALL IMMEDIATE");sql("SET CONSTRAINTS ALL DEFERRED");}
    String head()throws SQLException{String id=UUID.randomUUID().toString();sql("INSERT INTO public.mop_change_notice_draft(id,tenant_id,applicant_id) VALUES ('"+id+"','"+TENANT+"','"+actor+"')");return id;}
    ChangeNoticeDraft definition(String summary,Instant end,List<String> refs){return new ChangeNoticeDraft(UUID.fromString(TENANT),UUID.fromString(actor),null,summary,Instant.parse("2026-10-01T16:00:00.123Z"),end,refs.stream().map(UUID::fromString).toList());}
    ChangeNoticeDraft standard(){return definition("SYNTHETIC_CHANGE_NOTICE_SCHEMA",null,List.of(asset));}
    void revision(String id,int v,String action,ChangeNoticeDraft d,String digest)throws SQLException{
        try(var s=c.prepareStatement("INSERT INTO public.mop_change_notice_revision(tenant_id,notice_id,version,previous_version,recorded_by,action,archived,ticket_id,change_summary,planned_start_at,planned_end_at,asset_count,content_sha256) VALUES (?::uuid,?::uuid,?,?,?::uuid,?,?,?::uuid,?,?::timestamptz,?::timestamptz,?,?)")){
            s.setString(1,TENANT);s.setString(2,id);s.setInt(3,v);if(v==1)s.setNull(4,Types.BIGINT);else s.setInt(4,v-1);s.setString(5,actor);s.setString(6,action);s.setBoolean(7,action.equals("ARCHIVE"));s.setString(8,d.ticketId()==null?null:d.ticketId().toString());s.setString(9,d.changeSummary());s.setString(10,d.plannedStartAt().toString());s.setString(11,d.plannedEndAt()==null?null:d.plannedEndAt().toString());s.setInt(12,d.assetIds().size());s.setString(13,digest);s.executeUpdate();}
    }
    void target(String id,int v,int position,String ref)throws SQLException{sql("INSERT INTO public.mop_change_notice_asset(tenant_id,notice_id,version,position,asset_id) VALUES ('"+TENANT+"','"+id+"',"+v+","+position+",'"+ref+"')");}
    void complete(String id,int v,String action,ChangeNoticeDraft d)throws SQLException{revision(id,v,action,d,d.fingerprint());int n=0;for(var ref:d.assetIds())target(id,v,++n,ref.toString());if(v>1)sql("UPDATE public.mop_change_notice_draft SET version="+v+",updated_at=statement_timestamp() WHERE id='"+id+"'");validate();}
    String create()throws SQLException{String id=head();complete(id,1,"CREATE",standard());return id;}
    void rawRevision(String id,String extraColumns,String extraValues)throws SQLException{sql("INSERT INTO public.mop_change_notice_revision(tenant_id,notice_id,version,recorded_by,action,change_summary,planned_start_at,asset_count,content_sha256"+extraColumns+") VALUES ('"+TENANT+"','"+id+"',1,'"+actor+"','CREATE','SYNTHETIC','2026-10-01T16:00:00Z',1,'"+"a".repeat(64)+"'"+extraValues+")");}
    @Test void actualStructureAclAndGuardBodiesMatch()throws Exception{ChangeNoticeSchemaVerifier.verify(c);assertEquals("mop_test_runtime",scalar("SELECT current_user"));}
    @Test void approvalAndP3RemainUnknownWithoutSuppression()throws Exception{String id=create();assertEquals("true,true,false,false,false,false,DRAFT,CONFIG_PENDING,CONFIG_PENDING,Asia/Shanghai",scalar("SELECT (approval_status IS NULL)||','||(automatic_p3_decision IS NULL)||','||effective||','||approval_evidence_verified||','||device_execution_allowed||','||alert_suppression_allowed||','||lifecycle_status||','||approval_workflow_status||','||matching_policy_status||','||timezone FROM public.mop_change_notice_revision WHERE notice_id='"+id+"'"));}
    @Test void javaFingerprintMatchesPostgresForUnicodeOrderedAssetsAndKnownEnd()throws Exception{var d=definition(" 合成😀\n保留空格 ",Instant.parse("2026-10-02T01:01:02.345Z"),List.of(otherAsset,asset));String id=head();complete(id,1,"CREATE",d);assertEquals(d.fingerprint(),scalar("SELECT content_sha256 FROM public.mop_change_notice_revision WHERE notice_id='"+id+"'"));assertEquals(otherAsset+","+asset,scalar("SELECT string_agg(asset_id::text,',' ORDER BY position) FROM public.mop_change_notice_asset WHERE notice_id='"+id+"'"));}
    @Test void nullEndIsPreservedAndNotDefaulted()throws Exception{String id=create();assertEquals("true",scalar("SELECT (planned_end_at IS NULL)::text FROM public.mop_change_notice_revision WHERE notice_id='"+id+"'"));}
    @Test void wrongDigestAndWrongAssetOrderFailDeferredValidation()throws Exception{rejected("23514",()->{String id=head();revision(id,1,"CREATE",standard(),"0".repeat(64));target(id,1,1,asset);validate();});rejected("23514",()->{String id=head();var d=definition("SYNTHETIC",null,List.of(otherAsset,asset));revision(id,1,"CREATE",d,d.fingerprint());target(id,1,1,asset);target(id,1,2,otherAsset);validate();});}
    @Test void missingCurrentRevisionFailsDeferredValidation()throws Exception{rejected("23503",()->{head();validate();});}
    @Test void incompleteAssetsFailAtDeferredBoundary()throws Exception{rejected("23514",()->{String id=head();var d=definition("SYNTHETIC",null,List.of(asset,otherAsset));revision(id,1,"CREATE",d,d.fingerprint());target(id,1,1,asset);validate();});}
    @Test void foreignAssetAndUnknownOptionalTicketAreRejected()throws Exception{rejected("23503",()->{String id=head();revision(id,1,"CREATE",standard(),standard().fingerprint());target(id,1,1,foreignAsset);});rejected("23503",()->{var d=standard();var withTicket=new ChangeNoticeDraft(d.tenantId(),d.applicantId(),UUID.randomUUID(),d.changeSummary(),d.plannedStartAt(),null,d.assetIds());revision(head(),1,"CREATE",withTicket,withTicket.fingerprint());});}
    @Test void duplicateAndOutOfRangeAssetPositionsFail()throws Exception{String id=head();var d=definition("SYNTHETIC",null,List.of(asset,otherAsset));revision(id,1,"CREATE",d,d.fingerprint());target(id,1,1,asset);rejected("23505",()->target(id,1,2,asset));rejected("23514",()->target(id,1,3,otherAsset));}
    @Test void headCannotSkipOrRepeatVersion()throws Exception{String id=create();for(int v:List.of(0,1,3))rejected("23514",()->sql("UPDATE public.mop_change_notice_draft SET version="+v+" WHERE id='"+id+"'"));}
    @Test void futureRevisionWithoutHeadAdvanceFails()throws Exception{String id=create();rejected("23514",()->{revision(id,2,"UPDATE",standard(),standard().fingerprint());target(id,2,1,asset);validate();});}
    @Test void updateKeepsOriginalRevisionAndApplicant()throws Exception{String id=create();String before=scalar("SELECT to_jsonb(r)::text FROM public.mop_change_notice_revision r WHERE notice_id='"+id+"' AND version=1");complete(id,2,"UPDATE",definition("修改草稿",Instant.parse("2026-10-03T00:00:00Z"),List.of(otherAsset,asset)));assertEquals(before,scalar("SELECT to_jsonb(r)::text FROM public.mop_change_notice_revision r WHERE notice_id='"+id+"' AND version=1"));assertEquals(actor,scalar("SELECT applicant_id::text FROM public.mop_change_notice_draft WHERE id='"+id+"'"));}
    @Test void archiveRestorePreserveProposalAndRejectChangedSummaryOrWindow()throws Exception{String id=create();rejected("23514",()->complete(id,2,"ARCHIVE",definition("changed",null,List.of(asset))));rejected("23514",()->complete(id,2,"ARCHIVE",definition(standard().changeSummary(),Instant.parse("2026-10-03T00:00:00Z"),List.of(asset))));complete(id,2,"ARCHIVE",standard());rejected("23514",()->complete(id,3,"RESTORE",definition("changed",null,List.of(asset))));complete(id,3,"RESTORE",standard());assertEquals("CREATE,ARCHIVE,RESTORE",scalar("SELECT string_agg(action,',' ORDER BY version) FROM public.mop_change_notice_revision WHERE notice_id='"+id+"'"));}
    @Test void archivedUpdateAndUnneededRestoreAreRejected()throws Exception{String id=create();rejected("23514",()->complete(id,2,"RESTORE",standard()));complete(id,2,"ARCHIVE",standard());rejected("23514",()->complete(id,3,"UPDATE",standard()));}
    @Test void approvalSuppressionAndExecutionFlagsCannotBeInserted()throws Exception{for(String field:List.of("effective","approval_evidence_verified","device_execution_allowed","alert_suppression_allowed"))rejected("23514",()->rawRevision(head(),","+field,",true"));for(String field:List.of("approval_status","automatic_p3_decision"))rejected("23514",()->rawRevision(head(),","+field,",'APPROVED'"));}
    @Test void forgedCreationTransactionIsRejected()throws Exception{rejected("23514",()->rawRevision(head(),",creation_xid",",'1'::xid8"));}
    @Test void runtimeCannotRewriteDeleteTruncateOrRebindApplicant()throws Exception{String id=create();for(String table:List.of("mop_change_notice_draft","mop_change_notice_revision","mop_change_notice_asset")){rejected("42501",()->sql("DELETE FROM public."+table+" WHERE false"));rejected("42501",()->sql("TRUNCATE public."+table));}rejected("42501",()->sql("UPDATE public.mop_change_notice_draft SET applicant_id='"+actor+"' WHERE id='"+id+"'"));rejected("42501",()->sql("UPDATE public.mop_change_notice_revision SET change_summary='changed' WHERE notice_id='"+id+"'"));rejected("42501",()->sql("UPDATE public.mop_change_notice_asset SET position=2 WHERE notice_id='"+id+"'"));}
    @Test void committedRevisionCannotReceiveLaterAssets()throws Exception{String id=create();c.commit();rejected("23514",()->target(id,1,1,otherAsset));assertEquals("1",scalar("SELECT count(*) FROM public.mop_change_notice_asset WHERE notice_id='"+id+"'"));}
    @Test void earlyValidationDoesNotAllowExtraAsset()throws Exception{String id=create();sql("SET CONSTRAINTS ALL IMMEDIATE");rejected("23514",()->target(id,1,2,otherAsset));}
    void customValues(String summary,String start,String end)throws SQLException{String id=head();try(var q=c.prepareStatement("INSERT INTO public.mop_change_notice_revision(tenant_id,notice_id,version,recorded_by,action,change_summary,planned_start_at,planned_end_at,asset_count,content_sha256) VALUES (?::uuid,?::uuid,1,?::uuid,'CREATE',?,?::timestamptz,?::timestamptz,1,?)")){q.setString(1,TENANT);q.setString(2,id);q.setString(3,actor);q.setString(4,summary);q.setString(5,start);q.setString(6,end);q.setString(7,"a".repeat(64));q.executeUpdate();}}
    @Test void blankControlAndOversizeSummaryFailDatabaseValidation()throws Exception{for(String summary:List.of("","\u00a0","\ufeff","\u0001"))rejected("23514",()->customValues(summary,"2026-10-01T00:00:00Z",null));rejected("22001",()->customValues("😀".repeat(2001),"2026-10-01T00:00:00Z",null));}
    @Test void endMustBeStrictlyLaterAndShanghaiYearCannotOverflow()throws Exception{for(String end:List.of("2026-10-01T00:00:00Z","2026-09-30T23:59:59.999Z","9999-12-31T16:00:00Z"))rejected("23514",()->customValues("SYNTHETIC","2026-10-01T00:00:00Z",end));rejected("23514",()->customValues("SYNTHETIC","9999-12-31T16:00:00Z",null));}

}
